import random

class Game:
    def __init__(self):
        self.board = [[0 for _ in range(4)] for _ in range(4)]
        self.score = 0
        self.spawn_tile()
        self.spawn_tile()

    def spawn_tile(self):
        empty_cells = [(i, j) for i in range(4) for j in range(4) if self.board[i][j] == 0]
        if empty_cells:
            i, j = random.choice(empty_cells)
            self.board[i][j] = 2 if random.random() < 0.9 else 4

    def print_board(self):
        for row in self.board:
            print(' '.join(str(cell) if cell != 0 else '.' for cell in row))
        print(f"Score: {self.score}")

    def move(self, direction):
        moved = False
        new_board = self.board.copy()
        for i in range(4):
            row = []
            for j in range(4):
                if self.board[i][j] != 0:
                    row.append(self.board[i][j])
            if direction == 'w':
                row = self.merge(row)
                for j in range(4):
                    new_board[i][j] = row[j] if j < len(row) else 0
            elif direction == 's':
                row = self.merge(row[::-1])[::-1]
                for j in range(4):
                    new_board[i][j] = row[j] if j < len(row) else 0
            elif direction == 'a':
                col = [self.board[j][i] for j in range(4)]
                col = self.merge(col)
                for j in range(4):
                    new_board[j][i] = col[j] if j < len(col) else 0
            elif direction == 'd':
                col = [self.board[j][i] for j in range(4)]
                col = self.merge(col[::-1])[::-1]
                for j in range(4):
                    new_board[j][i] = col[j] if j < len(col) else 0
        if new_board != self.board:
            moved = True
            self.board = new_board
            self.spawn_tile()
            self.score += sum(self.get_merged_values())
        return moved

    def merge(self, row):
        new_row = []
        i = 0
        while i < len(row):
            if i + 1 < len(row) and row[i] == row[i + 1]:
                new_row.append(row[i] * 2)
                i += 2
            else:
                new_row.append(row[i])
                i += 1
        return new_row

    def get_merged_values(self):
        merged_values = []
        for i in range(4):
            for j in range(4):
                if self.board[i][j] != 0 and self.board[i][j] != self.board[i][j - 1] and j > 0:
                    merged_values.append(self.board[i][j])
        return merged_values

    def is_game_over(self):
        for i in range(4):
            for j in range(4):
                if self.board[i][j] == 0:
                    return False
        for i in range(4):
            for j in range(3):
                if self.board[i][j] == self.board[i][j + 1] or self.board[j][i] == self.board[j + 1][i]:
                    return False
        return True

    def is_game_won(self):
        return any(cell == 2048 for row in self.board for cell in row)
